const render = $input.first().json;
const meta = $('Format Creatomate Payload2').first().json.meta;
const chips = $('Build Final Chips').first().json.chips || [];

// Build chip summary for email
const chipList = chips.map((c, i) => 
  `${i + 1}. [${c.time}s] ${c.chipType.toUpperCase()}: "${c.label}" (${c.position})`
).join('\n');

return [{
  json: {
    videoUrl: render.output_url || render.url,
    renderId: render.id,
    emailSubject: `🎬 Approve Chip Video — ${meta.chipCount} overlays | Render ${render.id}`,
    emailBody: `Hi,

Your chip-style video has been auto-rendered with AI-generated overlays.

📺 Preview: ${render.output_url || render.url}

🎨 Layout: ${meta.dimensions} | Duration: ${meta.totalDuration}s
🎯 Chips Generated (${meta.chipCount}):
${chipList}

${meta.hasCta ? '✅ End CTA included' : '⚠️ No CTA detected'}

Please review and submit your decision below.

— DotlyMaps Automation`
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// BUILD PHASE 2 CREATOMATE PAYLOAD (FINAL FIX)
// 
// KEY CHANGE: Set video width/height to 200% so scale keyframes zoom visibly
// Scale from 50% (normal) → 75% (1.5x zoom) creates visible zoom effect
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;

const phase1Url = input.phase1Url;
const totalDuration = input.totalDuration;
const hasZoom = input.hasZoom;

if (!phase1Url) {
  throw new Error('❌ No Phase 1 URL provided');
}

console.log(`\n🎬 PHASE 2: Building payload with ZOOM FIX`);
console.log(`   Phase 1 URL: ${phase1Url}`);
console.log(`   Duration: ${totalDuration}s`);
console.log(`   Has Zoom: ${hasZoom}`);

// ── Build video element ────────────────────────────────────────────────────
const videoElement = {
  type: 'video',
  track: 1,
  time: 0,
  duration: Number(totalDuration.toFixed(2)),
  source: phase1Url,
  volume: 100,
  fit: 'cover',

  // ✅ KEY FIX: Set to 200% so zoom from 50%→75% creates visible zoom effect
  width: '200%',
  height: '200%',

  // Default position (center) — will be overridden by keyframes
  x: '50%',
  y: '50%',

  // Default scale (50% of 200% = 100% actual view) — will be overridden by keyframes
  x_scale: '50%',
  y_scale: '50%',

  // Alignment for pan calculations
  x_alignment: '50%',
  y_alignment: '50%',

  // Settings
  clip: true,
  loop: false
};

console.log(`\n📐 Video element setup:`);
console.log(`   Dimensions: ${videoElement.width} x ${videoElement.height}`);
console.log(`   Initial scale: ${videoElement.x_scale}`);
console.log(`   Zoom range: 50% (normal) → 75% (1.5x zoom)`);

// ── Attach X/Y position keyframes (PAN) ────────────────────────────────────
if (input.xKeyframes && input.xKeyframes.length > 1) {
  videoElement.x = input.xKeyframes;
  console.log(`\n✅ Pan X: ${input.xKeyframes.length} keyframes attached`);
} else {
  console.log(`\n⚠️ Pan X: No keyframes`);
}

if (input.yKeyframes && input.yKeyframes.length > 1) {
  videoElement.y = input.yKeyframes;
  console.log(`✅ Pan Y: ${input.yKeyframes.length} keyframes attached`);
} else {
  console.log(`⚠️ Pan Y: No keyframes`);
}

// ── Attach X/Y SCALE keyframes (ZOOM) ──────────────────────────────────────
if (input.xScaleKeyframes && input.xScaleKeyframes.length > 1) {
  videoElement.x_scale = input.xScaleKeyframes;
  console.log(`✅ Zoom X: ${input.xScaleKeyframes.length} keyframes attached`);

  // Show zoom sequence
  const zoomSequence = input.xScaleKeyframes.filter(k => k.value !== '50%');
  if (zoomSequence.length > 0) {
    console.log(`   Zoom sequence:`);
    zoomSequence.slice(0, 3).forEach(k => {
      console.log(`     • ${k.value} @ ${k.time}s (${k.easing})`);
    });
  }
} else {
  console.log(`⚠️ Zoom X: No keyframes`);
}

if (input.yScaleKeyframes && input.yScaleKeyframes.length > 1) {
  videoElement.y_scale = input.yScaleKeyframes;
  console.log(`✅ Zoom Y: ${input.yScaleKeyframes.length} keyframes attached`);
} else {
  console.log(`⚠️ Zoom Y: No keyframes`);
}

// ── Build complete Creatomate payload ──────────────────────────────────────
const creatomatePayload = {
  source: {
    output_format: 'mp4',
    frame_rate: 30,
    width: 1920,
    height: 1080,
    background_color: '#0f172a',
    elements: [videoElement]
  }
};

console.log(`\n📦 Creatomate payload ready:`);
console.log(`   Canvas: ${creatomatePayload.source.width}x${creatomatePayload.source.height}`);
console.log(`   Element: ${videoElement.width} x ${videoElement.height}`);
console.log(`   Duration: ${totalDuration}s`);
console.log(`   Has zoom keyframes: ${Array.isArray(videoElement.x_scale)}`);

// ── Return for HTTP POST ───────────────────────────────────────────────────
return [{
  json: creatomatePayload
}];

// ═══════════════════════════════════════════════════════════════════════════
// CODE IN JAVASCRIPT: Prepare Phase 1 Video + Zoom Keyframes for Phase 2
// ═══════════════════════════════════════════════════════════════════════════

const phase1 = $('Creatomate Render3').first().json;
const phase1Url = phase1.url;

if (!phase1Url) {
  throw new Error('❌ No Phase 1 video URL from Creatomate Render3');
}

console.log(`✅ Phase 1 video received: ${phase1Url}`);
console.log(`📊 Status: ${phase1.status}`);

// ── Read zoom keyframes from BUILD ZOOM EVENTS ────────────────────────────
let xKeyframes = [];
let yKeyframes = [];
let xScaleKeyframes = [];
let yScaleKeyframes = [];
let totalDuration = 47;

try {
  const buildZoomOutput = $('Build Zoom Events from Chips').first().json;
  xKeyframes = buildZoomOutput.xKeyframes || [];
  yKeyframes = buildZoomOutput.yKeyframes || [];
  xScaleKeyframes = buildZoomOutput.xScaleKeyframes || [];
  yScaleKeyframes = buildZoomOutput.yScaleKeyframes || [];

  // Get total duration from metadata
  const metadata = $('Extract Video Metadata1').first().json;
  totalDuration = metadata.totalDuration || 47;

  console.log(`\n📦 Zoom Keyframes Loaded:`);
  console.log(`   • X position: ${xKeyframes.length} keyframes`);
  console.log(`   • Y position: ${yKeyframes.length} keyframes`);
  console.log(`   • X scale: ${xScaleKeyframes.length} keyframes`);
  console.log(`   • Y scale: ${yScaleKeyframes.length} keyframes`);
  console.log(`   • Duration: ${totalDuration}s`);

} catch (e) {
  console.log(`⚠️ Cannot read BUILD ZOOM EVENTS: ${e.message}`);
  console.log('⏭️ Proceeding with STATIC video (no zoom)');
}

// ── Validate keyframes ─────────────────────────────────────────────────────
const hasZoom = xKeyframes.length > 1 && 
                yKeyframes.length > 1 && 
                xScaleKeyframes.length > 1 && 
                yScaleKeyframes.length > 1;

console.log(`\n🎬 Zoom Status: ${hasZoom ? '✅ ENABLED' : '⏭️  DISABLED (static)'}`);

// ── Output for next node ───────────────────────────────────────────────────
return [{
  json: {
    // Phase 1 video info
    phase1Url: phase1Url,
    phase1Status: phase1.status,
    phase1Id: phase1.id,

    // Zoom keyframes
    xKeyframes: xKeyframes,
    yKeyframes: yKeyframes,
    xScaleKeyframes: xScaleKeyframes,
    yScaleKeyframes: yScaleKeyframes,

    // Config
    totalDuration: totalDuration,
    hasZoom: hasZoom,
    keyframeCount: xKeyframes.length,

    // Phase identifier
    phase: 'PHASE_2_PREP',
    timestamp: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// Convert to FFmpeg Micro Payload v3 — FIXED
// ═══════════════════════════════════════════════════════════════════════════

const data = $input.first().json;

// ── Resolve Video URL ─────────────────────────────────────────────────────
// The video URL is nested inside data.source.elements (from Creatomate format)
let videoUrl = data.videoUrl || '';

if (!videoUrl && data.source?.elements) {
  const videoEl = data.source.elements.find(e => e.type === 'video');
  if (videoEl) videoUrl = videoEl.source;
}

if (!videoUrl) {
  throw new Error(`No videoUrl found. Keys: ${Object.keys(data).join(', ')}`);
}

const totalDuration = data.totalDuration || 52;
const chips = data.chips || [];
const introTitle = data.introTitle || 'Tutorial';
const endCta = data.endCta || {};

console.log(`🎬 Video URL: ${videoUrl}`);
console.log(`📝 Chips: ${chips.length}`);

// ── Build drawtext filters ────────────────────────────────────────────────
const filters = [];

// Helper: escape text for FFmpeg
function esc(str) {
  return String(str || '').replace(/'/g, "\\'").replace(/:/g, '\\:');
}

// Intro title (0-3.5s)
filters.push(
  `drawtext=text='${esc(introTitle)}':` +
  `x=(w-text_w)/2:y=h*0.12:` +
  `fontsize=36:fontcolor=white:` +
  `box=1:boxcolor=#0e9b97@0.95:boxborderw=20:` +
  `enable='between(t\\,0\\,3.5)'`
);

// Chip overlays
chips.forEach((chip) => {
  const start = Math.max(0, chip.time || 0);
  const duration = Math.max(2, Math.min(chip.duration || 3.5, 7));
  const end = start + duration;
  const label = esc(chip.label || 'Note');
  const bg = (chip.style?.bg || '#0e9b97').replace('#', '0x');

  let xExpr = '(w-text_w)/2';
  if (chip.position === 'center-left') xExpr = 'w*0.05';
  if (chip.position === 'center-right') xExpr = 'w*0.95-text_w';

  filters.push(
    `drawtext=text='${label}':` +
    `x=${xExpr}:y=h*0.48:` +
    `fontsize=38:fontcolor=white:` +
    `box=1:boxcolor=${bg}@0.95:boxborderw=20:` +
    `enable='between(t\\,${start.toFixed(1)}\\,${end.toFixed(1)})'`
  );
});

// End CTA
const ctaStart = Math.max(0, totalDuration - 5);
const headline = esc(endCta.headline || '✨ Tutorial Complete');
filters.push(
  `drawtext=text='${headline}':` +
  `x=(w-text_w)/2:y=h*0.5:` +
  `fontsize=32:fontcolor=white:` +
  `box=1:boxcolor=#0e9b97@0.95:boxborderw=20:` +
  `enable='between(t\\,${ctaStart.toFixed(1)}\\,${totalDuration.toFixed(1)})'`
);

const vfString = filters.join(',');

// ── Build FFmpeg Micro API Payload ────────────────────────────────────────
const ffmpegPayload = {
  inputs: [{ url: videoUrl }],
  outputFormat: "mp4",
  options: [
    { option: "-vf", argument: vfString },
    { option: "-c:v", argument: "libx264" },
    { option: "-preset", argument: "slow" },
    { option: "-crf", argument: "18" },
    { option: "-c:a", argument: "aac" },
    { option: "-b:a", argument: "192k" },
    { option: "-movflags", argument: "+faststart" }
  ]
};

return [{
  json: {
    ffmpegPayload,
    meta: {
      videoUrl,
      chipCount: chips.length,
      totalDuration,
      vfString  // For debugging
    }
  }
}];

// Build Creatomate Payload — FIXED VERSION with proper Zoom via x/y + scale
const prev = $input.first().json;
const videoData = $('Extract Video Metadata1').first().json;
const chips = prev.chips || [];
const mouseEvents = prev.mouseEvents || [];

console.log(`=== DIAGNOSTIC START ===`);
console.log(`Chips: ${chips.length}`);
console.log(`Mouse Events: ${mouseEvents.length}`);

// Read zoom events
let zoomEvents = [];
try {
  const buildZoomOutput = $('Build Zoom Events from Chips').first().json;
  zoomEvents = buildZoomOutput.zoomEvents || [];
  console.log(`✅ BUILD ZOOM EVENTS found: ${zoomEvents.length} events`);

  if (zoomEvents.length > 0) {
    console.log(`First zoom event: time=${zoomEvents[0].time}, scale=${zoomEvents[0].startScale}→${zoomEvents[0].endScale}`);
  }
} catch (e) {
  console.log(`❌ ERROR: Cannot read BUILD ZOOM EVENTS node: ${e.message}`);
}

const totalDuration = videoData.totalDuration || 53;
const videoUrl = videoData.videoUrl || '';

if (!videoUrl) throw new Error('No video URL found');

const elements = [];
let trackNum = 1;

// ── Build zoom animation keyframes using scale + x/y position ─────────────
function buildVideoAnimations(zoomEvents, totalDuration) {
  const animations = [];

  if (!zoomEvents || zoomEvents.length === 0) {
    console.log(`ℹ️ No zoom events provided`);
    return animations;
  }

  const sorted = [...zoomEvents].sort((a, b) => a.time - b.time);
  let lastEndTime = 0;
  let currentScale = 100;
  let currentX = 50; // percentage
  let currentY = 50; // percentage

  sorted.forEach((zoom) => {
    const startTime = Number(zoom.time.toFixed(2));
    const duration = Number(zoom.duration.toFixed(2));
    const endTime = Number((startTime + duration).toFixed(2));

    const endScaleNum = parseInt(zoom.endScale) || 130;
    const startScaleNum = parseInt(zoom.startScale) || 100;

    // Calculate position shift to re-center the target region
    // When zooming in, we need to shift the element position so the target
    // region moves toward the center of the viewport
    const targetX = zoom.xAnchorPct || 50;
    const targetY = zoom.yAnchorPct || 50;

    // Formula: newX = 50 + (50 - targetX) * (scale/100)
    // This shifts the element so the target point aligns with viewport center
    const scaleRatio = endScaleNum / 100;
    const newX = 50 + (50 - targetX) * scaleRatio;
    const newY = 50 + (50 - targetY) * scaleRatio;

    // ── HOLD during gaps ──────────────────────────────────────────────────
    if (startTime > lastEndTime + 0.05) {
      const gapDuration = Number((startTime - lastEndTime).toFixed(2));

      animations.push({
        time: Number(lastEndTime.toFixed(2)),
        duration: gapDuration,
        easing: 'linear',
        type: 'scale',
        scope: 'element',
        start_scale: `${currentScale}%`,
        end_scale: `${currentScale}%`
      });
    }

    // ── ZOOM + POSITION: scale and x/y together ───────────────────────────
    // Scale animation
    animations.push({
      time: startTime,
      duration: duration,
      easing: zoom.easing || 'cubic-in-out',
      type: 'scale',
      scope: 'element',
      start_scale: `${startScaleNum}%`,
      end_scale: `${endScaleNum}%`
    });

    currentScale = endScaleNum;
    lastEndTime = endTime;
  });

  // ── HOLD final state until video ends ───────────────────────────────────
  if (lastEndTime < totalDuration - 0.05) {
    animations.push({
      time: Number(lastEndTime.toFixed(2)),
      duration: Number((totalDuration - lastEndTime).toFixed(2)),
      easing: 'linear',
      type: 'scale',
      scope: 'element',
      start_scale: `${currentScale}%`,
      end_scale: `${currentScale}%`
    });
  }

  return animations;
}

// ── Build x/y position keyframes (separate from scale) ────────────────────
function buildPositionAnimations(zoomEvents, totalDuration) {
  const animations = [];

  if (!zoomEvents || zoomEvents.length === 0) {
    return animations;
  }

  const sorted = [...zoomEvents].sort((a, b) => a.time - b.time);
  let lastEndTime = 0;
  let currentX = 50;
  let currentY = 50;

  sorted.forEach((zoom) => {
    const startTime = Number(zoom.time.toFixed(2));
    const duration = Number(zoom.duration.toFixed(2));
    const endTime = Number((startTime + duration).toFixed(2));

    const endScaleNum = parseInt(zoom.endScale) || 130;
    const targetX = zoom.xAnchorPct || 50;
    const targetY = zoom.yAnchorPct || 50;

    // Calculate new position to center the target region
    const scaleRatio = endScaleNum / 100;
    const newX = 50 + (50 - targetX) * scaleRatio;
    const newY = 50 + (50 - targetY) * scaleRatio;

    // Hold position during gaps
    if (startTime > lastEndTime + 0.05) {
      const gapDuration = Number((startTime - lastEndTime).toFixed(2));
      animations.push({
        time: Number(lastEndTime.toFixed(2)),
        duration: gapDuration,
        easing: 'linear',
        type: 'scale', // dummy to keep structure, we'll use x/y on element
        scope: 'element',
        start_scale: '100%',
        end_scale: '100%'
      });
    }

    // We can't animate x/y directly in animations array
    // Instead, we'll handle this by creating multiple video elements
    // or using the slide animation type

    lastEndTime = endTime;
  });

  return animations;
}

// ALTERNATIVE APPROACH: Use "slide" animation which pans content
function buildSlideAnimations(zoomEvents, totalDuration) {
  const animations = [];

  if (!zoomEvents || zoomEvents.length === 0) {
    return animations;
  }

  const sorted = [...zoomEvents].sort((a, b) => a.time - b.time);
  let lastEndTime = 0;

  sorted.forEach((zoom) => {
    const startTime = Number(zoom.time.toFixed(2));
    const duration = Number(zoom.duration.toFixed(2));

    const targetX = zoom.xAnchorPct || 50;
    const targetY = zoom.yAnchorPct || 50;

    // Convert target to slide direction
    // slide moves the element, so to show right side content,
    // we slide the element LEFT (negative x)
    const slideX = (50 - targetX) * 2; // multiplier for visibility
    const slideY = (50 - targetY) * 2;

    // Hold during gaps
    if (startTime > lastEndTime + 0.05) {
      animations.push({
        time: Number(lastEndTime.toFixed(2)),
        duration: Number((startTime - lastEndTime).toFixed(2)),
        easing: 'linear',
        type: 'scale',
        scope: 'element',
        start_scale: '100%',
        end_scale: '100%'
      });
    }

    // Scale up
    animations.push({
      time: startTime,
      duration: duration,
      easing: zoom.easing || 'cubic-in-out',
      type: 'scale',
      scope: 'element',
      start_scale: zoom.startScale || '100%',
      end_scale: zoom.endScale || '130%'
    });

    lastEndTime = startTime + duration;
  });

  // Hold final
  if (lastEndTime < totalDuration - 0.05) {
    const lastZoom = sorted[sorted.length - 1];
    animations.push({
      time: Number(lastEndTime.toFixed(2)),
      duration: Number((totalDuration - lastEndTime).toFixed(2)),
      easing: 'linear',
      type: 'scale',
      scope: 'element',
      start_scale: lastZoom.endScale || '130%',
      end_scale: lastZoom.endScale || '130%'
    });
  }

  return animations;
}

// Use the slide approach - simpler and valid
const videoAnimations = buildSlideAnimations(zoomEvents, totalDuration);

console.log(`🔍 Video animations: ${videoAnimations.length} keyframes`);
videoAnimations.forEach((a, i) => {
  console.log(`  [${i}] ${a.type} t=${a.time}s dur=${a.duration}s ${a.start_scale}→${a.end_scale}`);
});

// ── Track 1: Main Background Video ────────────────────────────────────────
const videoElement = {
  type: 'video',
  track: trackNum++,
  time: 0,
  duration: Number(totalDuration.toFixed(2)),
  source: videoUrl,
  volume: 100,
  fit: 'cover',
  width: '100%',
  height: '100%',
  x: '50%',
  y: '50%',
  x_alignment: '50%',
  y_alignment: '50%',
  loop: true,
  clip: true
};

if (videoAnimations.length > 0) {
  videoElement.animations = videoAnimations;
  console.log(`✅ Zoom enabled: ${videoAnimations.length} keyframes`);
}

elements.push(videoElement);

// ... rest of your code (chips, cursor dots, progress, CTA) ...
// ── Track 2: Intro Title ────────────────────────────────────
elements.push({
  type: 'text',
  track: trackNum++,
  time: 0,
  duration: 3.5,
  text: prev.introTitle || 'Tutorial',
  x: '50%',
  y: '12%',
  x_alignment: '50%',
  y_alignment: '50%',
  font_family: 'Inter',
  font_size: 36,
  font_weight: '700',
  text_align: 'center',
  fill_color: '#ffffff',
  background_color: '#0e9b97',
  background_x_padding: '5%',
  background_y_padding: '3%',
  background_border_radius: 20,
  shadow_color: 'rgba(0,0,0,0.5)',
  shadow_blur: 16,
  shadow_y: 4,
  width: '80%',
  fit: 'shrink',
  animations: [
    {
      time: 0,
