      easing: 'quadratic-out',
      type: 'scale',
      scope: 'element',
      start_scale: '70%',
      end_scale: '100%',
      fade: true
    }
  ]
});

// ── Track 3+: Mouse Cursor Dots ─────────────────────────────
mouseEvents.forEach((m) => {
  const startTime = Number(m.time.toFixed(2));
  const duration = Number((m.duration || 1.0).toFixed(2));
  const xPos = `${(m.x * 100).toFixed(1)}%`;
  const yPos = `${(m.y * 100).toFixed(1)}%`;

  elements.push({
    type: 'text',
    track: trackNum++,
    time: startTime,
    duration: duration,
    text: '●',
    x: xPos,
    y: yPos,
    x_alignment: '50%',
    y_alignment: '50%',
    font_family: 'Inter',
    font_size: 28,
    font_weight: '700',
    text_align: 'center',
    fill_color: '#ffffff',
    shadow_color: 'rgba(59,130,246,0.9)',
    shadow_blur: 15,
    animations: [
      {
        time: 0,
        duration: 0.2,
        easing: 'quadratic-out',
        type: 'scale',
        scope: 'element',
        start_scale: '0%',
        end_scale: '100%',
        fade: true
      },
      {
        time: Number((duration - 0.2).toFixed(2)),
        duration: 0.2,
        easing: 'quadratic-in',
        type: 'scale',
        scope: 'element',
        start_scale: '100%',
        end_scale: '0%',
        fade: true
      }
    ]
  });

  elements.push({
    type: 'text',
    track: trackNum++,
    time: startTime,
    duration: duration,
    text: '○',
    x: xPos,
    y: yPos,
    x_alignment: '50%',
    y_alignment: '50%',
    font_family: 'Inter',
    font_size: 44,
    font_weight: '400',
    text_align: 'center',
    fill_color: 'rgba(255,255,255,0.35)',
    animations: [
      {
        time: 0,
        duration: 0.3,
        easing: 'quadratic-out',
        type: 'scale',
        scope: 'element',
        start_scale: '50%',
        end_scale: '130%',
        fade: true
      },
      {
        time: Number((duration - 0.3).toFixed(2)),
        duration: 0.3,
        easing: 'quadratic-in',
        type: 'scale',
        scope: 'element',
        start_scale: '130%',
        end_scale: '50%',
        fade: true
      }
    ]
  });
});

const positionMap = {
  'center-left': { x: '48%', y: '48%', x_a: '0%', y_a: '50%' },
  'center-right': { x: '50%', y: '48%', x_a: '100%', y_a: '50%' },
  center: { x: '50%', y: '48%', x_a: '50%', y_a: '50%' }
};

// ── Chip Overlays ───────────────────────────────────────────
chips.forEach((chip) => {
  const pos = positionMap[chip.position] || positionMap['center'];
  const duration = Math.max(2, Math.min(chip.duration || 3.5, 7));
  const time = Math.max(0, chip.time);
  const easing = chip.chipType === 'highlight' ? 'back-in-out' : 'quadratic-out';

  elements.push({
    type: 'text',
    track: trackNum++,
    time: Number(time.toFixed(2)),
    duration: Number(duration.toFixed(2)),
    text: chip.label || 'Note',
