// Greedy Pack & Build FFmpeg
// ═══════════════════════════════════════════════════════════════════════════

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error('Greedy Pack & Build FFmpeg: no input items received');
}

const input = inputItems[0].json ?? {};
const state = input.state || null;

if (!state) {
  throw new Error('Greedy Pack & Build FFmpeg: state missing');
}

const remainingChips =
  Array.isArray(input.remainingChips) ? input.remainingChips : [];

const pipelineIndex =
  Number(input.pipelineIndex ?? state.pipelineIndex ?? 1);

let currentVideoUrl = input.currentVideoUrl ?? state.currentVideoUrl ?? null;
let originalVideoUrl = input.originalVideoUrl ?? state.originalVideoUrl ?? null;

if (pipelineIndex === 1) {
  currentVideoUrl = originalVideoUrl;
}

if (!currentVideoUrl) {
  throw new Error(
    pipelineIndex === 1
      ? 'No originalVideoUrl found for pipeline 1'
      : 'No currentVideoUrl found for later pipeline'
  );
}

if (remainingChips.length === 0) {
  return [{
    json: {
      state,
      ffmpegPayload: null,
      pipelineIndex,
      currentVideoUrl,
      originalVideoUrl,
      renderedIndices: [],
      skippedIndices: [],
      renderedCount: 0,
      skippedCount: 0,
      filterSize: 0,
      status: 'nothing-to-render'
    }
  }];
}

function esc(value) {
  return String(value ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/:/g, '\\:')
    .replace(/,/g, '\\;')
    .replace(/\[/g, '\\[')
    .replace(/\]/g, '\\]');
}

function parseColor(color) {
  if (!color || color === 'transparent') return null;
  const value = String(color).trim();
  if (value.toLowerCase().startsWith('rgba')) {
    const match = value.match(/rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([\d.]+)\s*\)/i);
    if (match) {
      const hex = [1, 2, 3].map(i => Number(match[i]).toString(16).padStart(2, '0')).join('');
      return { hex, alpha: Number(match[4]).toFixed(2) };
    }
  }
  const hex = value.replace('#', '');
  return {
    hex: hex.length === 3 ? hex.split('').map(c => c + c).join('') : hex,
    alpha: '0.95'
  };
}

const BASE_FILTER =
  pipelineIndex === 1
    ? 'scale=1824:1026,pad=1920:1080:(ow-iw)/2:(oh-ih)/2:0f172a'
    : '';

const textFilterData = remainingChips.map(chip => {
  const text = esc(chip.text);
  const time = Number(chip.time ?? 0);
  const duration = Number(chip.duration ?? 3);
  const start = time.toFixed(2);
  const end = (time + duration).toFixed(2);
  const x = (Number.parseFloat(String(chip.x ?? '50')) / 100).toFixed(4);
  const y = (Number.parseFloat(String(chip.y ?? '50')) / 100).toFixed(4);
  const xAlignment = chip.x_alignment ?? '0%';
  const yAlignment = chip.y_alignment ?? '0%';
  const xOffset = xAlignment === '100%' ? '-tw' : xAlignment === '50%' ? '-tw/2' : '';
  const yOffset = yAlignment === '100%' ? '-th' : yAlignment === '50%' ? '-th/2' : '';
  const fontSize = Number(chip.font_size ?? 24);
  const fillColor = String(chip.fill_color ?? '#ffffff').replace('#', '');
  const background = parseColor(chip.background_color);

  let drawText =
    `drawtext=text='${text}':x=w*${x}${xOffset}:y=h*${y}${yOffset}:fontsize=${fontSize}:fontcolor=#${fillColor}`;

  if (background) {
    const borderWidth = Math.max(5, Math.round(fontSize * 0.25));
    drawText += `:box=1:boxcolor=#${background.hex}@${background.alpha}:boxborderw=${borderWidth}`;
  }

  drawText += `:enable='between(t\\,${start}\\,${end})'`;

  return {
    originalIndex: Number(chip.originalIndex ?? 0),
    text: String(chip.text ?? ''),
    filterSize: drawText.length,
    filterString: drawText
  };
});

const MAX_FILTER_LENGTH = 1900;
let currentFilterSize = BASE_FILTER.length;
const renderedChips = [];
const skippedChips = [];

for (const item of textFilterData) {
  const separatorSize = renderedChips.length > 0 ? 1 : 0;
  const sizeWithSeparator = item.filterSize + separatorSize;

  if (currentFilterSize + sizeWithSeparator <= MAX_FILTER_LENGTH) {
    renderedChips.push(item);
    currentFilterSize += sizeWithSeparator;
  } else {
    skippedChips.push(item);
  }
}

if (remainingChips.length > 0 && renderedChips.length === 0) {
  const firstChip = textFilterData[0];
  throw new Error(
    `No chip could fit within FFmpeg filter limit. First chip "${firstChip?.text}" requires ` +
    `${firstChip?.filterSize ?? 'unknown'} characters. Limit: ${MAX_FILTER_LENGTH}.`
  );
}

const vf = [BASE_FILTER, ...renderedChips.map(item => item.filterString)]
  .filter(Boolean)
  .join(',');

if (vf.length >= 2000) {
  throw new Error(`Final FFmpeg filter is too large: ${vf.length} characters`);
}

const ffmpegPayload = {
  inputs: [{ url: currentVideoUrl }],
  outputFormat: 'mp4',
  options: [
    { option: '-vf', argument: vf },
    { option: '-c:v', argument: 'libx264' },
    { option: '-preset', argument: 'slow' },
    { option: '-crf', argument: '18' },
    { option: '-an', argument: '' },
    { option: '-movflags', argument: '+faststart' },
    { option: '-pix_fmt', argument: 'yuv420p' }
  ]
};

return [{
  json: {
    state,
    ffmpegPayload,
    pipelineIndex,
    currentVideoUrl,
    originalVideoUrl,
    renderedIndices: renderedChips.map(item => item.originalIndex),
    skippedIndices: skippedChips.map(item => item.originalIndex),
    renderedCount: renderedChips.length,
    skippedCount: skippedChips.length,
    totalRemainingBeforePass: remainingChips.length,
    filterSize: vf.length,
    status: 'ready'
  }
}];

