// Build Final Chips — Sequential: Gemini → OpenRouter → Here
const meta = $('Extract Video Metadata1').first().json;

// ── Primary: OpenRouter enriched chips ────────────────────────
let openRouterChips = [];
let introTitle = '';
let endCta = null;

try {
  const orData = $('Normalize OpenRouter Response').first().json;
  openRouterChips = orData.chips || [];
  introTitle = orData.introTitle || meta.videoName;
  endCta = orData.endCta || null;
  console.log('✅ OpenRouter enriched:', openRouterChips.length, 'chips');
} catch (e) {
  console.log('⚠️ OpenRouter failed:', e.message);
}

// ── Fallback: Gemini raw chips & mouseEvents ────────────────
let geminiChips = [];
let geminiMouseEvents = [];

try {
  const geminiData = $('Parse Gemini Analysis').first().json;
  geminiChips = geminiData.chips || [];
  geminiMouseEvents = geminiData.mouseEvents || [];
  console.log('✅ Gemini:', geminiChips.length, 'chips,', geminiMouseEvents.length, 'mouse events');
} catch (e) {
  console.log('⚠️ Gemini unavailable:', e.message);
}

// ── Merge chips: OpenRouter primary, Gemini fills gaps ──────
const mergedChips = [...openRouterChips];

geminiChips.forEach(gChip => {
  const tooClose = openRouterChips.some(o => Math.abs(o.time - gChip.time) < 3);
  if (!tooClose) {
    mergedChips.push({
      ...gChip,
      source: 'gemini-fallback'
    });
  }
});

mergedChips.sort((a, b) => a.time - b.time);

let mouseEvents = [...geminiMouseEvents];

if (mouseEvents.length === 0) {
  console.log('🖱️ Fallback: building mouseEvents from chip positions');
  mergedChips.forEach(chip => {
    if (chip.clickX !== undefined && chip.clickY !== undefined) {
      mouseEvents.push({
        time: Math.max(0, chip.time + 1.5 - 0.3),
        duration: 1.2,
        x: chip.clickX,
        y: chip.clickY,
        element: chip.element || 'UI Element'
      });
    }
  });
}

console.log(`🖱️ Final: ${mouseEvents.length} mouse events`);

if (mergedChips.length === 0) {
  throw new Error('No valid chips from any AI source');
}

return [{
  json: {
    videoUrl: meta.videoUrl,
    videoName: meta.videoName,
    totalDuration: meta.totalDuration,
    desiredLayout: meta.desiredLayout,
    introTitle: introTitle || meta.videoName,
    endCta: endCta,
    chips: mergedChips,
    mouseEvents: mouseEvents,
    chipCount: mergedChips.length,
    cursorCount: mouseEvents.length,
    fromOpenRouter: openRouterChips.length > 0,
    fromGemini: geminiChips.length > 0,
    // ✅ UPDATED: brand teal changed from old Storyly teal (#0e9b97) to new logo-matched teal
    style: {
      fontFamily: 'Inter',
      bg: '#0d9488',            // brand teal (logo core color)
      text: '#ffffff',
      backgroundColor: '#000000'
    }
  }
}];

// Normalize OpenRouter Response → Creatomate-compatible chips
const input = $input.first().json;

// Extract content
let content = $input.first().json.content.parts[0].text;

// Clean markdown
content = content.replace(/```json\s*|```\s*/g, '').trim();
const jsonMatch = content.match(/\{[\s\S]*\}/);
if (jsonMatch) content = jsonMatch[0];

let enriched = {};
try {
  enriched = JSON.parse(content);
} catch (e) {
  throw new Error(`Failed to parse OpenRouter JSON: ${e.message}`);
}

// Get Gemini data for position correction
const gemini = $('Parse Gemini Analysis').first().json;
const geminiEvents = gemini.timeline || [];

// Build lookup: time -> Gemini event for position matching
const geminiByTime = {};
geminiEvents.forEach(e => {
  const key = Math.round(e.timestamp);
  geminiByTime[key] = e;
});

// ── SAFETY: label length cap (defense-in-depth against the AI ignoring the prompt limit) ──
const MAX_LABEL_LEN = 32;
function capLabel(str) {
  const s = String(str || 'Action');
  return s.length > MAX_LABEL_LEN ? s.slice(0, MAX_LABEL_LEN - 1).trim() + '…' : s;
}

// Normalize chips
const normalizedChips = (enriched.chips || []).map((chip, index) => {
  // ✅ FIX (Issue #2 / Phase 2): make display/click timing EXPLICIT and consistent.
  // chip.time from "Message a model" is DISPLAY time (when the text appears).
  // The actual user click always happens 2s AFTER display time.
  const displayTime = Math.max(0, chip.time);
  const clickTime = displayTime + 2; // ← single source of truth for click time from here on

  // Find nearest Gemini event for better positioning (lookup uses click time, not display time)
  const chipTimeRounded = Math.round(clickTime);
  const geminiEvt = geminiByTime[chipTimeRounded] || geminiByTime[chipTimeRounded - 1] || geminiByTime[chipTimeRounded + 1];

  // Determine position based on Gemini's click position (opposite side, near center)
  let position = chip.position || 'center';
  if (geminiEvt && geminiEvt.position) {
    const px = geminiEvt.position.x || 0.5;
    if (px > 0.55)       position = 'center-left';
    else if (px < 0.45)  position = 'center-right';
    else                 position = 'center';
  }

  // Hard-enforce: never allow corner positions
  const horizontalPos = position.includes('left') ? 'center-left'
                      : position.includes('right') ? 'center-right'
                      : 'center';
  position = horizontalPos;

  // Ensure style has both bg and text
  // Ensure style has both bg and text
  // ✅ UPDATED: fallback brand color changed from '#0e9b97' to '#0d9488' (new brand teal)
  const style = {
    bg: chip.style?.bg || '#0d9488',
    text: chip.style?.text || '#ffffff'
  };

  const safeLabel = capLabel(chip.label);

  return {
    time: displayTime,             // kept for backward-compat with any node still reading `chip.time`
    displayTime: displayTime,      // ✅ NEW: explicit display time (when text overlay appears)
    clickTime: clickTime,          // ✅ NEW: explicit click time (displayTime + 2s), replaces old ambiguous chipTime
    duration: chip.duration || 3.5,
    chipType: chip.chipType || 'info',
    label: safeLabel,
    description: chip.description || safeLabel,
    position: position,
    style: style,
    voiceText: chip.description || safeLabel,
    // ✅ Pass through click coordinates exactly as given (used for zoom targeting downstream)
    clickX: chip.clickX,   // may be undefined
    clickY: chip.clickY,   // may be undefined
    source: 'openrouter-enriched'
  };
});

// Deduplicate: merge chips at same time
const deduped = [];
const seenTimes = new Set();
normalizedChips.forEach(chip => {
  const key = Math.round(chip.time * 2) / 2; // Round to nearest 0.5s
  if (!seenTimes.has(key)) {
    seenTimes.add(key);
    deduped.push(chip);
  }
});

deduped.sort((a, b) => a.time - b.time);

// Build endCta
const hasError = (gemini.errors || []).length > 0;
const endCta = enriched.endCta || {
  headline: hasError ? '⚠️ Tutorial Complete' : '✨ Tutorial Complete',
  subheadline: 'Start mapping your data today',
  buttonText: 'Get Started',
  website: 'https://dotlymaps.com'
};

// Safety cap on introTitle — same 35-char ceiling requested in the prompt
const rawIntroTitle = enriched.introTitle || 'Tutorial';
const introTitle = String(rawIntroTitle).length > 35
  ? String(rawIntroTitle).slice(0, 34).trim() + '…'
  : rawIntroTitle;

return [{
  json: {
    chips: deduped,
    chipCount: deduped.length,
    introTitle: introTitle,
    endCta: endCta,
    fromOpenRouter: true,
    rawTokens: input.usage?.total_tokens || 0
  }
}];

const data = $input.first().json;

// ✅ UPDATED: SEMANTIC_COLORS now maps to the new brand palette (teal → cyan → sky → indigo),
// matching the same set used in the Shotstack actionColors table, so chip colors stay
// consistent across the Creatomate render and the Shotstack text-overlay render.
const SEMANTIC_COLORS = {
  '#06b6d4': 'highlight',    // cyan - clicks/buttons
  '#4338ca': 'protip',       // indigo - text input
  '#0d9488': 'info',         // brand teal - dropdowns
  '#0ea5e9': 'warning',      // sky blue - popups
  '#3730a3': 'error',        // deep indigo - errors
  '#14b8a6': 'success',      // aqua - success
  '#64748b': 'neutral',      // slate - scroll/zoom (unchanged)
  '#1e3a8a': 'chapter'       // navy - chapter markers
};

// ✅ UPDATED: brand color for anything not in semantic map — now brand teal, not old Storyly teal
const BRAND_COLOR = '#0d9488';

const brandedChips = data.chips.map(c => {
  const chipBg = c.style?.bg || '';
  const isSemantic = !!SEMANTIC_COLORS[chipBg];
  const finalBg = isSemantic ? chipBg : BRAND_COLOR;

  return {
    ...c,
    displayTime: c.displayTime !== undefined ? c.displayTime : c.time,
    clickTime: c.clickTime !== undefined ? c.clickTime : (c.time + 2),
    style: {
      bg: finalBg,
      text: '#ffffff'
    }
  };
});

return [{
  json: {
    ...data,
    chips: brandedChips,
    style: {
      fontFamily: data.style?.fontFamily || 'Inter',
      bg: BRAND_COLOR,
      text: '#ffffff',
      backgroundColor: '#000000'
    }
  }
}];

