      { time: Number((duration - 0.2).toFixed(2)), duration: 0.2, easing: 'quadratic-in', type: 'scale', scope: 'element', start_scale: '100%', end_scale: '0%', fade: true }
    ]
  });

  elements.push({
    type: 'text', track: trackNum++, time: startTime, duration, text: '○', x: xPos, y: yPos,
    x_alignment: '50%', y_alignment: '50%', font_family: 'Inter', font_size: 44, font_weight: '400',
    text_align: 'center', fill_color: 'rgba(255,255,255,0.35)',
    animations: [
      { time: 0, duration: 0.3, easing: 'quadratic-out', type: 'scale', scope: 'element', start_scale: '50%', end_scale: '130%', fade: true },
      { time: Number((duration - 0.3).toFixed(2)), duration: 0.3, easing: 'quadratic-in', type: 'scale', scope: 'element', start_scale: '130%', end_scale: '50%', fade: true }
    ]
  });
});

const positionMap = {
  'center-left': { x: '48%', x_a: '0%' },
  'center-right': { x: '52%', x_a: '100%' },
  'center': { x: '50%', x_a: '50%' }
};

const TEXT_ZOOM_BUFFER = 0.1;
const MIN_TEXT_DURATION = 0.5;
const MAX_TEXT_DURATION_NO_ZOOM = 7;

chips.forEach((chip) => {
  const pos = positionMap[chip.position] || positionMap['center'];

  const displayTime = Math.max(0, chip.displayTime !== undefined ? chip.displayTime : chip.time);
  const clickTime = chip.clickTime !== undefined ? chip.clickTime : displayTime + 2;

  let duration;
  if (chip.clickX !== undefined && chip.clickY !== undefined) {
    const zoomStartTime = clickTime - 1.0;
    duration = Math.max(MIN_TEXT_DURATION, zoomStartTime - displayTime - TEXT_ZOOM_BUFFER);
  } else {
    duration = Math.max(2, Math.min(chip.duration || 3.5, MAX_TEXT_DURATION_NO_ZOOM));
  }

  const time = displayTime;
  const easing = chip.chipType === 'highlight' ? 'back-in-out' : 'quadratic-out';

  // ✅ UPDATED: default chip background fallback changed from '#0e9b97' to '#0d9488'
  elements.push({
    type: 'text', track: trackNum++, time: Number(time.toFixed(2)), duration: Number(duration.toFixed(2)),
    text: chip.label || 'Note', x: pos.x, y: '48%', x_alignment: pos.x_a, y_alignment: '50%',
    font_family: 'Inter', font_size: 38, font_weight: '700', text_align: 'center', fill_color: '#ffffff',
