    font_family: 'Inter', font_size: 12, font_weight: '600', text_align: 'right', fill_color: '#64748b',
    background_color: 'rgba(15, 23, 42, 0.6)', background_x_padding: '1.5%', background_y_padding: '1%',
    background_border_radius: 6,
    animations: [{ time: 0, duration: 0.3, easing: 'quadratic-out', type: 'scale', scope: 'element', start_scale: '0%', end_scale: '100%', fade: true }]
  });
}

// ✅ UPDATED: end CTA background + glow shadow changed from old teal to new brand teal
const endTime = Math.max(0, totalDuration - 5);
elements.push({
  type: 'text', track: trackNum++, time: Number(endTime.toFixed(2)), duration: 5,
  text: prev.endCta?.headline || '✨ Tutorial Complete', x: '50%', y: '50%', x_alignment: '50%', y_alignment: '50%',
