      totalDuration, hasCta: !!prev.endCta, hasBackground: true, dimensions: '1920x1080',
      fromOpenRouter: prev.fromOpenRouter || false, fromGemini: prev.fromGemini || false
    }
  }
}];

const staticData = $getWorkflowStaticData('global');

const baseVideo = $('Edit Fields3').first().json.secure_video_url;
