// Prepare Narration Segments1
// ─ FIX: was referencing a non-existent node "Analyze video1" — now correctly
//   reads from "Analyze video", the actual Gemini analysis node.
// ═══════════════════════════════════════════════════════════════════════════

const raw = $('Analyze video1').first().json;

const text = raw.content?.parts?.[0]?.text || raw.text || '';
if (!text) throw new Error('Gemini analysis text not found');

let data;
try {
  data = JSON.parse(text);
} catch (error) {
  throw new Error(`Gemini analysis JSON parse failed: ${error.message}`);
}

const actualVideo = $('Edit Fields3').first().json;
const videoDuration = Number(actualVideo.duration || data.videoAnalysis?.duration || 0);
const videoUrl = actualVideo.secure_video_url || '';

if (!videoUrl) throw new Error('Final video URL not found');
if (!videoDuration || videoDuration <= 0) throw new Error('Valid video duration not found');

let segments = [];

if (Array.isArray(data.narrationSegments) && data.narrationSegments.length) {
  segments = data.narrationSegments.map((s, index) => ({
    startTime: Number(s.startTime),
    type: s.type || 'chip',
    chipIndex: s.chipIndex == null ? null : Number(s.chipIndex),
    label: s.label || (s.chipIndex != null && data.chips?.[Number(s.chipIndex)]?.label) || '',
    text: String(s.text || '').trim(),
    originalIndex: index
  }));
} else if (Array.isArray(data.chips) && data.chips.length) {
  segments = data.chips.map((chip, index) => ({
    startTime: Number(chip.time),
    type: 'chip',
    chipIndex: index,
    label: chip.label || '',
    text: String(chip.voiceText || '').trim(),
    originalIndex: index
  }));
}

segments = segments
  .filter(s => s.text && Number.isFinite(s.startTime) && s.startTime >= 0 && s.startTime < videoDuration)
  .sort((a, b) => a.startTime - b.startTime || a.originalIndex - b.originalIndex);

const seen = new Set();
segments = segments.filter(s => {
  const key = `${s.startTime}|${s.type}|${s.text}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

segments = segments.map((s, index) => ({
  ...s,
  segmentIndex: index,
  totalSegments: segments.length,
  videoDuration,
  videoUrl,
  startTimeMs: Math.round(s.startTime * 1000)
}));

if (!segments.length) throw new Error('No valid narration segments found');

return segments.map(s => ({ json: s }));

