// ═══════════════════════════════════════════════════════════════════════════
// Extract URL + Preserve Loop State
// ═══════════════════════════════════════════════════════════════════════════

const cloudinary =
  $input.first()?.json ?? {};

const secureUrl =
  cloudinary.secure_url;

if (!secureUrl) {
  throw new Error(
    'Extract URL: Cloudinary did not return secure_url'
  );
}

let greedy;

try {
  greedy =
    $('Greedy Pack & Build FFmpeg')
      .first()
      .json;
} catch (error) {
  throw new Error(
    `Extract URL: cannot read Greedy Pack result: ${error.message}`
  );
}

if (!greedy) {
  throw new Error(
    'Extract URL: Greedy Pack result is missing'
  );
}

