// Parse Gemini Video Analyzer Response — with timestamp parsing fix
const input = $input.first().json;

// Extract text from Gemini's response structure
let text = '';
if (input.content && input.content.parts && input.content.parts[0]) {
  text = input.content.parts[0].text || '';
} else if (input.candidates && input.candidates[0] && input.candidates[0].content) {
  text = input.candidates[0].content.parts[0].text || '';
} else if (typeof input === 'string') {
  text = input;
}

// Clean markdown wrappers
text = text
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let analysis = {};
try {
  analysis = JSON.parse(text);
} catch (e) {
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      analysis = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      throw new Error(`Failed to parse Gemini response: ${e2.message}\nRaw: ${text.substring(0, 500)}`);
    }
  } else {
    throw new Error(`No JSON found. Raw: ${text.substring(0, 500)}`);
  }
}

// ── Timestamp parser: "00:08.5" → 8.5 ───────────────────────────────
function parseTimestamp(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value !== 'string') return 0;

  const raw = value.trim();

  // Plain number (e.g., "8.5")
  if (/^\d+(?:\.\d+)?$/.test(raw)) {
    return parseFloat(raw);
  }

  // MM:SS(.ms) or HH:MM:SS(.ms)
  if (raw.includes(':')) {
    const parts = raw.split(':').map(Number);
    if (parts.length === 3) {
      return parts[0] * 3600 + parts[1] * 60 + parts[2];
    }
    if (parts.length === 2) {
      return parts[0] * 60 + parts[1];
    }
  }

  // Fallback: try extracting a number
  const match = raw.match(/(\d+(?:\.\d+)?)/);
  if (match) return parseFloat(match[0]);

  return 0;
}

// ── EXTRACT CURSOR EVENTS FROM FRAMES ──────────────────────────────
const cursorEvents = [];
const mouseEvents = [];

if (analysis.frames && Array.isArray(analysis.frames)) {
  analysis.frames.forEach(frame => {
    const ts = parseTimestamp(frame.timestamp);

    // Extract cursor position/state
    if (frame.cursor && frame.cursor.position) {
      const pos = frame.cursor.position;
      const state = frame.cursor.state || 'default';
      cursorEvents.push({
        timestamp: ts,
        type: state === 'clicked' ? 'click' : 'move',
        position: pos,
        state: state,
        x: pos.x,
        y: pos.y
      });

      if (state === 'clicked') {
        mouseEvents.push({
          time: Math.max(0, ts - 0.3),
          duration: 1.2,
          x: pos.x,
          y: pos.y,
          element: 'UI Element'
        });
      }
    }

    // Also extract click positions from ui_events
    if (frame.ui_events && Array.isArray(frame.ui_events)) {
      frame.ui_events.forEach(evt => {
        if (evt.position && evt.eventType === 'cursor_clicked') {
          const alreadyExists = mouseEvents.some(m =>
            Math.abs(m.time - (ts - 0.3)) < 0.5
          );
          if (!alreadyExists) {
            mouseEvents.push({
              time: Math.max(0, ts - 0.3),
              duration: 1.2,
              x: evt.position.x,
              y: evt.position.y,
              element: evt.element || 'UI Element'
            });
          }
        }
      });
    }
  });
}

