const scaleFactor = Math.min(CANVAS_W / sourceWidth, CANVAS_H / sourceHeight);
const scaledW = sourceWidth * scaleFactor;
const scaledH = sourceHeight * scaleFactor;
const padX = (CANVAS_W - scaledW) / 2;
const padY = (CANVAS_H - scaledH) / 2;

console.log(`   Source: ${sourceWidth}x${sourceHeight} | Scaled: ${scaledW.toFixed(1)}x${scaledH.toFixed(1)} | Pad: x=${padX.toFixed(1)} y=${padY.toFixed(1)}`);

function remapClick(clickX, clickY) {
  return {
    targetX: (padX + clickX * scaledW) / CANVAS_W,
    targetY: (padY + clickY * scaledH) / CANVAS_H
  };
}

const BASE_SCALE = 50;
const DESIRED_ZOOM_SCALE = 75;
const MAX_ZOOM_SCALE = 110;

function computeAdaptiveZoomScale(targetX, targetY) {
  const marginX = Math.min(targetX, 1 - targetX);
  const marginY = Math.min(targetY, 1 - targetY);
  const margin = Math.min(marginX, marginY);
  const requiredMultiplier = margin > 0 ? 1 / (2 * margin) : MAX_ZOOM_SCALE / BASE_SCALE;
  const desiredMultiplier = DESIRED_ZOOM_SCALE / BASE_SCALE;
  const finalMultiplier = Math.min(Math.max(desiredMultiplier, requiredMultiplier), MAX_ZOOM_SCALE / BASE_SCALE);
  return Math.round(finalMultiplier * BASE_SCALE);
}

