// ── Deduplicate ────────────────────────────────────────────────────────
function deduplicateChips(chipsIn, timeThresholdSec = 1.5, distThreshold = 0.2) {
  const getTime = c => c.displayTime !== undefined ? c.displayTime : c.time;
  const sorted = [...chipsIn].sort((a, b) => getTime(a) - getTime(b));
  const merged = [];
  for (const chip of sorted) {
    const last = merged[merged.length - 1];
    if (last) {
      const timeDiff = Math.abs(getTime(chip) - getTime(last));
      const dist = Math.hypot((chip.clickX || 0.5) - (last.clickX || 0.5), (chip.clickY || 0.5) - (last.clickY || 0.5));
      if (timeDiff <= timeThresholdSec && dist <= distThreshold) {
        if (getTime(chip) > getTime(last)) merged[merged.length - 1] = chip;
        continue;
      }
    }
    merged.push(chip);
  }
  return merged;
}

