// ─── FFmpeg zoompan filter builder ──────────────────────────────────
function easeInOut(pVar) {
  return `if(lt(${pVar}\\,0.5)\\,4*pow(${pVar}\\,3)\\,1-4*pow(1-${pVar}\\,3))`;
}

function buildCombinedZoompan(zooms) {
  if (zooms.length === 0) return '';
  function buildNested(zooms, axis) {
    if (zooms.length === 0) {
      return axis === 'z' ? '1' : axis === 'x' ? 'iw*(1-1/zoom)/2' : 'ih*(1-1/zoom)/2';
    }
    const zoom = zooms[0];
    const actualZoom = (zoom.targetScale || DESIRED_ZOOM_SCALE) / BASE_SCALE;
    const rest = zooms.slice(1);
    const sF = Math.round(zoom.zoomStart * FPS);
    const pF = Math.round(zoom.panEnd * FPS);
    const ziF = Math.round(zoom.zoomInEnd * FPS);
    const hF = Math.round(zoom.holdEnd * FPS);
    const eF = Math.round(zoom.zoomOutEnd * FPS);

    if (axis === 'z') {
      const zIn = `(on-${pF})/(${ziF}-${pF})`;
      const zOut = `(on-${hF})/(${eF}-${hF})`;
      const easeIn = easeInOut(zIn);
      const easeOut = easeInOut(zOut);
      const zoomInExpr = `1+${(actualZoom-1).toFixed(4)}*${easeIn}`;
      const zoomOutExpr = `${actualZoom.toFixed(4)}-${(actualZoom-1).toFixed(4)}*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,1\\,if(between(on\\,${pF}\\,${ziF})\\,${zoomInExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${actualZoom.toFixed(4)})))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'z')})`;
    } else if (axis === 'x') {
      const targetX = zoom.targetX.toFixed(4);
      const centerX = `iw*(1-1/zoom)/2`;
      const targetXVal = `max(0\\,min(iw*(1-1/zoom)\\,iw*(${targetX}-1/(2*zoom))))`;
      const panProgress = `(on-${sF})/(${pF}-${sF})`;
      const easePan = easeInOut(panProgress);
      const panExpr = `${centerX}+(${targetXVal}-${centerX})*${easePan}`;
      const zOutProgress = `(on-${hF})/(${eF}-${hF})`;
      const easeOut = easeInOut(zOutProgress);
      const zoomOutExpr = `${targetXVal}+(${centerX}-${targetXVal})*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,${panExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${targetXVal}))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'x')})`;
    } else {
      const targetY = zoom.targetY.toFixed(4);
      const centerY = `ih*(1-1/zoom)/2`;
      const targetYVal = `max(0\\,min(ih*(1-1/zoom)\\,ih*(${targetY}-1/(2*zoom))))`;
      const panProgress = `(on-${sF})/(${pF}-${sF})`;
      const easePan = easeInOut(panProgress);
      const panExpr = `${centerY}+(${targetYVal}-${centerY})*${easePan}`;
      const zOutProgress = `(on-${hF})/(${eF}-${hF})`;
      const easeOut = easeInOut(zOutProgress);
      const zoomOutExpr = `${targetYVal}+(${centerY}-${targetYVal})*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,${panExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${targetYVal}))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'y')})`;
    }
  }
  const zExpr = buildNested(zooms, 'z');
  const xExpr = buildNested(zooms, 'x');
  const yExpr = buildNested(zooms, 'y');
  return `zoompan=z='${zExpr}':x='${xExpr}':y='${yExpr}':d=1:s=1920x1080:fps=25`;
}

function buildCursorFilters(cursors) { return ''; }

// ─── Pack into chunks ────────────────────────────────────────────────
const MAX_FILTER_LENGTH = 1800;
const chunks = [];
let zoomIdx = 0, cursorIdx = 0;

while (zoomIdx < allZooms.length || cursorIdx < allCursors.length) {
  const renderedZooms = [], renderedCursors = [];
  let filterString = '';

  while (zoomIdx < allZooms.length) {
    const testZooms = renderedZooms.concat(allZooms[zoomIdx]);
    const testFilter = buildCombinedZoompan(testZooms) + (renderedCursors.length ? ',' + buildCursorFilters(renderedCursors) : '');
    if (testFilter.length <= MAX_FILTER_LENGTH) { renderedZooms.push(allZooms[zoomIdx]); zoomIdx++; } else break;
  }
  while (cursorIdx < allCursors.length) {
    const testCursors = renderedCursors.concat(allCursors[cursorIdx]);
    const zoomPart = buildCombinedZoompan(renderedZooms);
    const cursorPart = buildCursorFilters(testCursors);
    const testFilter = zoomPart + (cursorPart ? ',' + cursorPart : '');
    if (testFilter.length <= MAX_FILTER_LENGTH) { renderedCursors.push(allCursors[cursorIdx]); cursorIdx++; } else break;
  }

  if (renderedZooms.length === 0 && renderedCursors.length === 0) break;

  const zoomPart = buildCombinedZoompan(renderedZooms);
  const cursorPart = buildCursorFilters(renderedCursors);
  filterString = zoomPart + (cursorPart ? ',' + cursorPart : '');

  chunks.push({ chunkIndex: chunks.length, zooms: renderedZooms, cursors: renderedCursors, filterString, filterStringLength: filterString.length });
}

if (chunks.length === 0) {
