      const zoomInExpr = `1+${(actualZoom-1).toFixed(4)}*${easeIn}`;
      const zoomOutExpr = `${actualZoom.toFixed(4)}-${(actualZoom-1).toFixed(4)}*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,1\\,if(between(on\\,${pF}\\,${ziF})\\,${zoomInExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${actualZoom.toFixed(4)})))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'z')})`;
    } else if (axis === 'x') {
      const targetX = zoom.targetX.toFixed(4);
      const centerX = `iw*(1-1/zoom)/2`;
      const targetXVal = `max(0\\,min(iw*(1-1/zoom)\\,iw*(${targetX}-1/(2*zoom))))`;
      const panProgress = `(on-${sF})/(${pF}-${sF})`;
      const easePan = easeInOut(panProgress);
      const panExpr = `${centerX}+(${targetXVal}-${centerX})*${easePan}`;
      const zOutProgress = `(on-${hF})/(${eF}-${hF})`;
      const easeOut = easeInOut(zOutProgress);
      const zoomOutExpr = `${targetXVal}+(${centerX}-${targetXVal})*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,${panExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${targetXVal}))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'x')})`;
    } else {
      const targetY = zoom.targetY.toFixed(4);
      const centerY = `ih*(1-1/zoom)/2`;
      const targetYVal = `max(0\\,min(ih*(1-1/zoom)\\,ih*(${targetY}-1/(2*zoom))))`;
      const panProgress = `(on-${sF})/(${pF}-${sF})`;
      const easePan = easeInOut(panProgress);
      const panExpr = `${centerY}+(${targetYVal}-${centerY})*${easePan}`;
      const zOutProgress = `(on-${hF})/(${eF}-${hF})`;
      const easeOut = easeInOut(zOutProgress);
      const zoomOutExpr = `${targetYVal}+(${centerY}-${targetYVal})*${easeOut}`;
      const block = `if(between(on\\,${sF}\\,${pF})\\,${panExpr}\\,if(between(on\\,${hF}\\,${eF})\\,${zoomOutExpr}\\,${targetYVal}))`;
      return `if(between(on\\,${sF}\\,${eF})\\,${block}\\,${buildNested(rest, 'y')})`;
    }
  }

  const zExpr = buildNested(zooms, 'z');
  const xExpr = buildNested(zooms, 'x');
  const yExpr = buildNested(zooms, 'y');

  return `zoompan=z='${zExpr}':x='${xExpr}':y='${yExpr}':d=1:s=1920x1080:fps=${TARGET_FPS}`;
}

