// ═══════════════════════════════════════════════════════════════════════════
// BUILD ZOOM EVENTS v9 — "Build Zoom Events from Chips" (FIXED per Issue #6)
// - ✅ FIX: Source of truth is now the merged/refined chips from "Build Final Chips",
//   NOT Gemini's raw cursor_clicked timeline. This guarantees a 1:1 correspondence
//   between text chips and zoom events (previously Gemini could have 10+ raw clicks
//   vs only 5-8 refined chips, causing extra/mismatched zooms).
// - ✅ FIX: click time is computed from chip.clickTime (or displayTime+2 fallback),
//   consistent with Normalize OpenRouter Response / Apply branding.
// - Keeps all existing zoom/pan/keyframe-building logic intact.
// ═══════════════════════════════════════════════════════════════════════════

const buildFinalChips = $('Build Final Chips').first().json;

// Safely normalize total duration to number
const totalDurationRaw =
  buildFinalChips.totalDuration ??
  buildFinalChips.duration ??
  47;

const totalDuration = Number(totalDurationRaw) || 47;

// ✅ FIX: pull chips (not Gemini timeline) as the source of truth
const chips = Array.isArray(buildFinalChips.chips) ? buildFinalChips.chips : [];

// ── Constants ─────────────────────────────────────────────────────────────
const PAN_DURATION    = 0.5;
const ZOOM_IN_DUR     = 0.8;
const HOLD_DUR        = 1.5;
const ZOOM_OUT_DUR    = 0.8;
const MIN_GAP         = 0.5;

const BASE_SCALE      = 50;   // 50% of 200% = 100% actual (normal)
const ZOOM_SCALE      = 75;   // 75% of 200% = 150% actual (1.5x zoom)

// ═══════════════════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════════════════

// Normalize coordinate to 0–1. Some upstream chips may still carry raw pixel
// values (a known upstream data-quality issue) — clamp defensively either way.
function normalizeCoordinate(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0.5;
  if (numeric >= 0 && numeric <= 1) return numeric;      // already normalized
  if (numeric > 1 && numeric <= 1920) return numeric / 1920; // looks like a pixel value (assume 1920 width basis)
  return Math.max(0, Math.min(1, numeric));               // safety clamp
}

// ═══════════════════════════════════════════════════════════════════════════
// COLLECT ZOOM-ELIGIBLE CHIPS (must have click coordinates)
// ═══════════════════════════════════════════════════════════════════════════

const clickChips = chips.filter(chip =>
  chip.clickX !== undefined && chip.clickY !== undefined
);

console.log(`🎯 Zoom-eligible chips (from refined chip source): ${clickChips.length} / ${chips.length} total chips`);

// Sort chronologically by click time
const sortedChips = [...clickChips].sort((a, b) => {
  const aClick = a.clickTime !== undefined ? a.clickTime : (a.displayTime ?? a.time) + 2;
  const bClick = b.clickTime !== undefined ? b.clickTime : (b.displayTime ?? b.time) + 2;
  return aClick - bClick;
});

// ═══════════════════════════════════════════════════════════════════════════
// BUILD SEQUENCES
// Zoom starts 1 second BEFORE the actual click (which is displayTime + 2s)
// ═══════════════════════════════════════════════════════════════════════════

const sequences = [];
let cursorTime = 0;

sortedChips.forEach(chip => {
  // ✅ FIX: explicit displayTime/clickTime, consistent with the rest of the pipeline
  const displayTime = chip.displayTime !== undefined ? chip.displayTime : chip.time;
  const actualClickTime = chip.clickTime !== undefined ? chip.clickTime : displayTime + 2;

  let zoomStart = actualClickTime - 1.0;
  zoomStart = Math.max(zoomStart, cursorTime);

  const panEnd     = zoomStart + PAN_DURATION;
  const zoomInEnd  = panEnd + ZOOM_IN_DUR;
  const holdEnd    = zoomInEnd + HOLD_DUR;
  const zoomOutEnd = holdEnd + ZOOM_OUT_DUR;

  if (zoomOutEnd >= totalDuration - 0.5) {
    return; // not enough room left in the video for this zoom
  }

  const px = normalizeCoordinate(chip.clickX);
  const py = normalizeCoordinate(chip.clickY);

  // ═══════════════════════════════════════════════════════════════════════
  // PAN FORMULA (unchanged from original — Creatomate x_alignment=50%/y_alignment=50%)
  // ═══════════════════════════════════════════════════════════════════════
  const zoomFactor = ZOOM_SCALE / BASE_SCALE; // 1.5x
  const visibleFraction = 1 / zoomFactor;     // 0.667
  const maxOffset = 50 * visibleFraction;     // 33.3

  const targetX = 50 + maxOffset * (1 - 2 * px);
  const targetY = 50 + maxOffset * (1 - 2 * py);

  const clampedX = Math.max(20, Math.min(80, targetX));
  const clampedY = Math.max(20, Math.min(80, targetY));

  sequences.push({
    element: chip.label,
    chipLabel: chip.label,
    displayTime,          // ✅ NEW: carried through for downstream consumers
    clickTime: actualClickTime,

    zoomStart,
    panEnd,
    zoomInEnd,
    holdEnd,
    zoomOutEnd,

    targetX: clampedX,
    targetY: clampedY,

    targetScale: ZOOM_SCALE
  });

  // Prevent overlapping sequences
  cursorTime = zoomOutEnd + MIN_GAP;
});

console.log(`✅ Built ${sequences.length} zoom sequences from ${clickChips.length} zoom-eligible chips (1:1 by design)`);

// ═══════════════════════════════════════════════════════════════════════════
// BUILD KEYFRAME TRACKS (unchanged logic)
// ═══════════════════════════════════════════════════════════════════════════

const xTrack = [{ time: 0, easing: 'linear', value: '50%' }];
const yTrack = [{ time: 0, easing: 'linear', value: '50%' }];
const xScaleTrack = [{ time: 0, easing: 'linear', value: `${BASE_SCALE}%` }];
const yScaleTrack = [{ time: 0, easing: 'linear', value: `${BASE_SCALE}%` }];

sequences.forEach(s => {
  const tx = `${s.targetX.toFixed(1)}%`;
  const ty = `${s.targetY.toFixed(1)}%`;
  const ts = `${s.targetScale}%`;

  // 1. Pan to target
  xTrack.push({ time: Number(s.panEnd.toFixed(2)), easing: 'cubic-in-out', value: tx });
  yTrack.push({ time: Number(s.panEnd.toFixed(2)), easing: 'cubic-in-out', value: ty });

  // 2. Zoom in
  xScaleTrack.push({ time: Number(s.zoomInEnd.toFixed(2)), easing: 'cubic-out', value: ts });
  yScaleTrack.push({ time: Number(s.zoomInEnd.toFixed(2)), easing: 'cubic-out', value: ts });

  // 3. Hold zoom
  xScaleTrack.push({ time: Number(s.holdEnd.toFixed(2)), easing: 'linear', value: ts });
  yScaleTrack.push({ time: Number(s.holdEnd.toFixed(2)), easing: 'linear', value: ts });

  // 4. Zoom out + return to center
  xScaleTrack.push({ time: Number(s.zoomOutEnd.toFixed(2)), easing: 'cubic-in-out', value: `${BASE_SCALE}%` });
  yScaleTrack.push({ time: Number(s.zoomOutEnd.toFixed(2)), easing: 'cubic-in-out', value: `${BASE_SCALE}%` });
  xTrack.push({ time: Number(s.zoomOutEnd.toFixed(2)), easing: 'cubic-in-out', value: '50%' });
  yTrack.push({ time: Number(s.zoomOutEnd.toFixed(2)), easing: 'cubic-in-out', value: '50%' });
});

// ── Final safety reset ──────────────────────────────────────────────────
const lastTime = Math.max(
  xTrack[xTrack.length - 1]?.time || 0,
  xScaleTrack[xScaleTrack.length - 1]?.time || 0
);

if (lastTime < totalDuration) {
  xTrack.push({ time: Number(totalDuration.toFixed(2)), easing: 'linear', value: '50%' });
  yTrack.push({ time: Number(totalDuration.toFixed(2)), easing: 'linear', value: '50%' });
  xScaleTrack.push({ time: Number(totalDuration.toFixed(2)), easing: 'linear', value: `${BASE_SCALE}%` });
  yScaleTrack.push({ time: Number(totalDuration.toFixed(2)), easing: 'linear', value: `${BASE_SCALE}%` });
}

// ═══════════════════════════════════════════════════════════════════════════
// OUTPUT
// ═══════════════════════════════════════════════════════════════════════════

return [
  {
    json: {
      ...($input.first().json),

      xKeyframes: xTrack,
      yKeyframes: yTrack,

      xScaleKeyframes: xScaleTrack,
      yScaleKeyframes: yScaleTrack,

      zoomCount: sequences.length,
      zoomSequences: sequences
    }
  }
];

