// ═══════════════════════════════════════════════════════════════════════
// Dynamic Custom Source JSON → Shotstack Render Payload  vPRO-9
//
// FIX: Only apply background-color to text elements that explicitly
// have background_color set in the source. This prevents cursor
// indicators (● / ○) from becoming solid blocks.
//
// FIX: Overlapping text stacking only applies to elements that share
// the same horizontal alignment AND are NOT exact duplicates.
// ═══════════════════════════════════════════════════════════════════════

const input = $input.first().json;
const source = input?.source || input;

if (!source || !Array.isArray(source.elements)) {
  throw new Error('Expected source.elements array');
}

// ═══════════════════════════════════════════════════════════════════════
// BASIC HELPERS
// ═══════════════════════════════════════════════════════════════════════

function toNumber(value, fallback = 0) {
  if (value === undefined || value === null || value === '') return fallback;
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function parsePercent(value, fallback = 50) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'number') return value;
  const str = String(value).trim();
  if (str.endsWith('%')) {
    const n = parseFloat(str);
    return Number.isFinite(n) ? n : fallback;
  }
  const n = parseFloat(str);
  return Number.isFinite(n) ? n : fallback;
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ═══════════════════════════════════════════════════════════════════════
// CANVAS
// ═══════════════════════════════════════════════════════════════════════

const CANVAS_WIDTH = toNumber(source.width, 1920);
const CANVAS_HEIGHT = toNumber(source.height, 1080);

// ═══════════════════════════════════════════════════════════════════════
// DIMENSION HELPERS
// ═══════════════════════════════════════════════════════════════════════

function dimensionToPixels(value, base, fallbackPercent) {
  if (value === undefined || value === null || value === '') {
    return Math.round(base * fallbackPercent / 100);
  }
  if (typeof value === 'number') return Math.round(value);
  const str = String(value).trim();
  if (str.endsWith('%')) {
    const pct = parseFloat(str);
    if (Number.isFinite(pct)) {
      return Math.round(base * pct / 100);
    }
  }
  const px = parseFloat(str);
  if (Number.isFinite(px)) return Math.round(px);
  return Math.round(base * fallbackPercent / 100);
}

function getOffsetFromXY(x, y) {
  const px = parsePercent(x, 50);
  const py = parsePercent(y, 50);

  // Shotstack: positive x moves right, positive y moves DOWN
  const offsetX = (px - 50) / 50;
  const offsetY = (py - 50) / 50;

  const result = {};
  if (Math.abs(offsetX) >= 0.001) result.x = Number(clamp(offsetX, -1, 1).toFixed(4));
  if (Math.abs(offsetY) >= 0.001) result.y = Number(clamp(offsetY, -1, 1).toFixed(4));

  return Object.keys(result).length ? result : undefined;
}

function mapFit(fit) {
  switch (String(fit || '').toLowerCase()) {
    case 'contain': return 'contain';
    case 'cover': return 'crop';
    case 'fill': return 'cover';
    case 'none': return 'none';
    default: return 'contain';
  }
}

function mapTransition(animations) {
  if (!Array.isArray(animations) || animations.length === 0) return undefined;

  const hasScale = animations.some(a => a?.type === 'scale');
  const hasFade = animations.some(a => a?.fade === true);

  if (hasScale && hasFade) return { in: 'zoom', out: 'fade' };
  if (hasScale) return { in: 'zoom' };
  if (hasFade) return { in: 'fade', out: 'fade' };
  return undefined;
}

// ═══════════════════════════════════════════════════════════════════════
// TEXT SIZING (hugs content)
// ═══════════════════════════════════════════════════════════════════════

function estimateTextWidth(text, fontSize, fontWeight = 400) {
  const str = String(text || '');
  const charCount = str.length;
  const weightFactor = Number(fontWeight) >= 700 ? 0.60 : 0.54;
  const estimated = charCount * fontSize * weightFactor;
  return Math.max(estimated, fontSize * 3);
}

function calculateFontSize(text, requestedFontSize, fontWeight, availableWidth) {
  let fontSize = toNumber(requestedFontSize, 32);
  const estimated = estimateTextWidth(text, fontSize, fontWeight);

  const target = availableWidth * 0.90;
  if (estimated > target) {
    const factor = target / estimated;
    fontSize = Math.floor(fontSize * factor);
  }

  return Math.round(clamp(fontSize, 18, 120));
}

function calculateTextBoxWidth(el) {
  const fontSize = toNumber(el.font_size, 32);
  const fontWeight = el.font_weight || 400;
  const text = String(el.text || '');

  const estimated = estimateTextWidth(text, fontSize, fontWeight);
  const horizontalPadding = CANVAS_WIDTH * 0.06;

  let naturalWidth = estimated + horizontalPadding;

  // Apply max width if provided (e.g., "80%")
  if (el.width !== undefined && el.width !== null && el.width !== '') {
    const maxWidth = dimensionToPixels(el.width, CANVAS_WIDTH, 80);
    naturalWidth = Math.min(naturalWidth, maxWidth);
  }

  const minWidth = fontSize * 4;
  const maxAllowed = CANVAS_WIDTH * 0.90;

  return Math.round(clamp(naturalWidth, minWidth, maxAllowed));
}

function calculateTextHeight(text, fontSize, width, backgroundPaddingY) {
  const estimatedTextWidth = estimateTextWidth(text, fontSize, 700);
  const usableWidth = Math.max(width - 80, 200);
  const estimatedLines = Math.max(1, Math.ceil(estimatedTextWidth / usableWidth));

  const paddingPercent = parsePercent(backgroundPaddingY, 3);
  const verticalPadding = Math.max(20, Math.round(CANVAS_HEIGHT * paddingPercent / 100));

  const lineHeight = Math.ceil(fontSize * 1.25);
  return Math.round(estimatedLines * lineHeight + verticalPadding * 2 + 10);
}

// ═══════════════════════════════════════════════════════════════════════
// OVERLAPPING TEXT BLOCK ADJUSTMENT (FIXED DUPLICATES)
// ═══════════════════════════════════════════════════════════════════════

function getTextHeightForLayout(el) {
  const boxWidth = calculateTextBoxWidth(el);
  const fontSize = calculateFontSize(String(el.text || ''), toNumber(el.font_size, 32), el.font_weight || 400, boxWidth);
  return calculateTextHeight(String(el.text || ''), fontSize, boxWidth, el.background_y_padding || '3%');
}

function adjustOverlappingTextPositions(elements, canvasHeight) {
  const textElements = elements.filter(el => el.type === 'text');
  textElements.sort((a, b) => {
    const aTime = toNumber(a.time, 0);
    const bTime = toNumber(b.time, 0);
    if (aTime !== bTime) return aTime - bTime;
    return (toNumber(a.track, 1) - toNumber(b.track, 1));
  });

  const placedElements = [];

  for (const el of textElements) {
    const elStart = toNumber(el.time, 0);
    const elDuration = toNumber(el.duration, 1);
    const elEnd = elStart + elDuration;

    const offsetObj = getOffsetFromXY(el.x, el.y);
    const elXOffset = offsetObj?.x || 0;
    const elYPct = parsePercent(el.y, 50);

    let overlapFound = false;
    let lowestY = -Infinity;

    for (const placed of placedElements) {
      const pStart = placed.time;
      const pEnd = pStart + placed.duration;

      // Only stack if they overlap in time AND share the same horizontal alignment
      if (elStart < pEnd && elEnd > pStart && Math.abs(placed.xOffset - elXOffset) < 0.05) {

        // NEW FIX: Skip exact duplicates (same text, same time, same x/y)
        if (el.text === placed.text && Math.abs(elXOffset - placed.xOffset) < 0.05 && Math.abs(elYPct - placed.yPctOriginal) < 0.5) {
          continue;
        }

        overlapFound = true;
        const placedBottomY = placed.yPct + (placed.height / canvasHeight) * 100;
        if (placedBottomY > lowestY) {
          lowestY = placedBottomY;
        }
      }
    }

    if (overlapFound) {
      const gapPx = 20;
      const gapPct = (gapPx / canvasHeight) * 100;
      const newYPct = lowestY + gapPct;
      el.y = Number(newYPct.toFixed(4));
    }

    const height = getTextHeightForLayout(el);
    placedElements.push({
      time: elStart,
      duration: elDuration,
      height: height,
      yPct: parsePercent(el.y, 50),
      yPctOriginal: elYPct, // Store original Y for duplicate check
      xOffset: elXOffset,
      text: el.text
    });
  }
}

// ═══════════════════════════════════════════════════════════════════════
// HTML TEXT ASSET – background ONLY if explicitly set
// ═══════════════════════════════════════════════════════════════════════

function buildHtmlAsset(el) {
  const text = String(el.text ?? '');
  const fontFamily = el.font_family || 'Inter';
  const requestedFontSize = toNumber(el.font_size, 32);
  const fontWeight = el.font_weight || 400;

  // Default width/height (will be used for all text, but we adjust padding)
  const boxWidth = calculateTextBoxWidth(el);
  const fontSize = calculateFontSize(text, requestedFontSize, fontWeight, boxWidth);
  const boxHeight = calculateTextHeight(text, fontSize, boxWidth, el.background_y_padding || '3%');

  // Build style parts conditionally
  const styles = [
    `font-family:${fontFamily},-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif`,
    `font-size:${fontSize}px`,
    `font-weight:${fontWeight}`,
    `color:${el.fill_color || '#ffffff'}`,
    `text-align:${el.text_align || 'center'}`,
    `white-space:normal`,
    `overflow-wrap:break-word`,
    `word-break:normal`,
    `display:flex`,
    `align-items:center`,
    `justify-content:center`,
    `box-sizing:border-box`,
    `margin:0`,
  ];

  // Only add background and related styles if background_color is explicitly defined
  const hasBackground = el.background_color !== undefined && el.background_color !== null && el.background_color !== '';

  if (hasBackground) {
    const paddingX = el.background_x_padding || '5%';
    const paddingY = el.background_y_padding || '3%';
    const borderRadius = toNumber(el.background_border_radius, 16);
    const shadowBlur = toNumber(el.shadow_blur, 0);
    const shadowY = toNumber(el.shadow_y, 0);
    const shadowColor = el.shadow_color || 'rgba(0,0,0,0.15)';

    styles.push(`padding-left:${paddingX}`);
    styles.push(`padding-right:${paddingX}`);
    styles.push(`padding-top:${paddingY}`);
    styles.push(`padding-bottom:${paddingY}`);
    styles.push(`background-color:${el.background_color}`);
    styles.push(`border-radius:${borderRadius}px`);
    styles.push(`border:1.5px solid rgba(255,255,255,0.28)`);
    styles.push(`box-shadow:0 0 0 1px rgba(0,0,0,0.05), 0 6px 18px rgba(0,0,0,0.14), 0 16px 40px ${shadowColor}, inset 0 1px 0 rgba(255,255,255,0.4)`);
    styles.push(`text-shadow:0 2px 4px rgba(0,0,0,0.22),0 1px 2px rgba(0,0,0,0.14)`);
    styles.push(`letter-spacing:-0.25px`);
    styles.push(`line-height:1.35`);
    styles.push(`max-width:${boxWidth}px`);
    styles.push(`animation:slideIn 0.5s cubic-bezier(0.22,1,0.36,1) forwards`);
  } else {
    // No background – minimal styling, no padding, no box shadow, no border.
    // We still set a max-width to avoid overflow, but no background.
    styles.push(`max-width:${boxWidth}px`);
    // No padding, no border, no shadow.
  }

  const html = `
<div style="${styles.join(';')}">
  ${escapeHtml(text)}
</div>
${hasBackground ? `
<style>
@keyframes slideIn {
  from { transform:translateY(16px) scale(0.9); opacity:0; filter:blur(4px); }
  to   { transform:translateY(0) scale(1); opacity:1; filter:blur(0); }
}
</style>` : ''}`;

  return {
    type: 'html',
    html: html.trim(),
    css: '',
    width: boxWidth,
    height: boxHeight,
  };
}

// ═══════════════════════════════════════════════════════════════════════
// ASSET MAPPING
// ═══════════════════════════════════════════════════════════════════════

function mapAsset(el) {
  if (el.type === 'image') {
    return { type: 'image', src: el.source };
  }

  if (el.type === 'video') {
    const asset = {
      type: 'video',
      src: el.source,
    };
    if (el.volume !== undefined && el.volume !== null && el.volume !== '') {
      asset.volume = clamp(toNumber(el.volume, 100) / 100, 0, 1);
    }
    return asset;
  }

  if (el.type === 'text') {
    return buildHtmlAsset(el);
  }

  throw new Error(`Unsupported element type: ${el.type}`);
}

// ═══════════════════════════════════════════════════════════════════════
// CLIP BUILDER
// ═══════════════════════════════════════════════════════════════════════

function mapElementToClip(el) {
  const clip = {
    asset: mapAsset(el),
    start: Math.max(0, toNumber(el.time, 0)),
    length: Math.max(0.01, toNumber(el.duration, 1)),
    position: 'center',
  };

  if (el.type === 'image' || el.type === 'video') {
    const width = dimensionToPixels(el.width, CANVAS_WIDTH, el.type === 'video' ? 95 : 100);
    const height = dimensionToPixels(el.height, CANVAS_HEIGHT, el.type === 'video' ? 95 : 100);
    clip.width = width;
    clip.height = height;
    clip.fit = mapFit(el.fit);
    const offset = getOffsetFromXY(el.x, el.y);
    if (offset) clip.offset = offset;
  }

  if (el.type === 'text') {
    const offset = getOffsetFromXY(el.x, el.y);
    if (offset) clip.offset = offset;
  }

  const transition = mapTransition(el.animations);
  if (transition) clip.transition = transition;

  return clip;
}

// ═══════════════════════════════════════════════════════════════════════
// REMOVE DUPLICATE VIDEO CLIPS
// ═══════════════════════════════════════════════════════════════════════

function isDuplicateVideo(a, b) {
  return (
    a?.type === 'video' &&
    b?.type === 'video' &&
    a.source === b.source &&
    toNumber(a.track, 0) === toNumber(b.track, 0) &&
    toNumber(a.time, 0) === toNumber(b.time, 0) &&
    toNumber(a.duration, 0) === toNumber(b.duration, 0)
  );
}

// ═══════════════════════════════════════════════════════════════════════
// BUILD TRACK MAP
// ═══════════════════════════════════════════════════════════════════════

// Adjust overlapping text positions before building tracks
adjustOverlappingTextPositions(source.elements, CANVAS_HEIGHT);

const tracksMap = new Map();

for (const element of source.elements) {
  if (!element || !element.type) continue;
  const trackNumber = Math.max(1, toNumber(element.track, 1));
  if (!tracksMap.has(trackNumber)) tracksMap.set(trackNumber, []);
  tracksMap.get(trackNumber).push(element);
}

// Remove duplicate videos within each track
for (const [trackNumber, elements] of tracksMap.entries()) {
  const cleaned = [];
  for (const element of elements) {
    if (element.type !== 'video') {
      cleaned.push(element);
      continue;
    }
    const duplicate = cleaned.some(existing => isDuplicateVideo(existing, element));
    if (!duplicate) cleaned.push(element);
  }
  tracksMap.set(trackNumber, cleaned);
}

// ═══════════════════════════════════════════════════════════════════════
// LAYER ORDER – tracks[0] is topmost, so reverse sort
// ═══════════════════════════════════════════════════════════════════════

const sortedEntries = [...tracksMap.entries()].sort((a, b) => b[0] - a[0]);

const shotstackTracks = sortedEntries
  .map(([_, elements]) => ({
    clips: elements.map(mapElementToClip).filter(Boolean),
  }))
  .filter(track => Array.isArray(track.clips) && track.clips.length > 0);

// ═══════════════════════════════════════════════════════════════════════
// RESOLUTION
// ═══════════════════════════════════════════════════════════════════════

function getResolution(width, height) {
  const w = toNumber(width);
  const h = toNumber(height);
  if (w >= 3840 || h >= 2160) return '4k';
  if (w >= 1920 || h >= 1080) return '1080';
  if (w >= 1280 || h >= 720) return '720';
  return 'sd';
}

// ═══════════════════════════════════════════════════════════════════════
// FINAL PAYLOAD
// ═══════════════════════════════════════════════════════════════════════

const payload = {
  timeline: {
    background: source.background_color || '#000000',
    tracks: shotstackTracks,
  },
  output: {
    format: source.output_format || 'mp4',
    resolution: getResolution(source.width, source.height),
    fps: toNumber(source.frame_rate, 30),
  },
};

return [{ json: payload }];
